--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `order_id` int NOT NULL AUTO_INCREMENT,
  `customer_id` int DEFAULT NULL,
  `customer_name` varchar(255) NOT NULL,
  `phone` varchar(20) NOT NULL,
  `email` varchar(255) DEFAULT NULL,
  `address` text NOT NULL,
  `note` text,
  `total_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `status` enum('PENDING','CONFIRMED','PACKING','SHIPPING','DELIVERED','RECEIVED','FAILED','CANCELLED') DEFAULT 'PENDING',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `payment_method` enum('COD','MOMO') DEFAULT 'COD',
  `payment_status` enum('UNPAID','PAID','REFUNDED') DEFAULT 'UNPAID',
  `order_date` datetime DEFAULT CURRENT_TIMESTAMP,
  `expected_delivery_date` datetime DEFAULT NULL,
  `delivered_at` datetime DEFAULT NULL,
  `confirmed_received_at` datetime DEFAULT NULL,
  `shipper_name` varchar(255) DEFAULT NULL,
  `shipper_phone` varchar(20) DEFAULT NULL,
  `tracking_code` varchar(100) DEFAULT NULL,
  `shipper_id` int DEFAULT NULL,
  `momo_order_id` varchar(255) DEFAULT NULL,
  `momo_transaction_id` varchar(255) DEFAULT NULL,
  `payment_time` datetime DEFAULT NULL,
  `cancel_reason` text,
  `failed_reason` text,
  `order_code` varchar(50) DEFAULT NULL,
  `address_id` int DEFAULT NULL,
  `lookup_code` varchar(20) DEFAULT NULL,
  `guest_token` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`order_id`),
  UNIQUE KEY `lookup_code` (`lookup_code`),
  KEY `fk_order_customer` (`customer_id`),
  KEY `fk_order_shipper` (`shipper_id`),
  CONSTRAINT `fk_order_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`customer_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_order_shipper` FOREIGN KEY (`shipper_id`) REFERENCES `shippers` (`shipper_id`)
) ENGINE=InnoDB AUTO_INCREMENT=148 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

